import React, { Suspense, lazy } from 'react';
import { Routes, Route } from 'react-router-dom';
import { useAuth } from './context/AuthContext';
import { PageLoader } from './components/common/Loader';
import ProtectedRoute, { PublicOnlyRoute } from './components/auth/ProtectedRoute';

const HomePage = lazy(() => import('./pages/HomePage'));
const LoginPage = lazy(() => import('./pages/LoginPage'));
const RegisterPage = lazy(() => import('./pages/RegisterPage'));
const DashboardPage = lazy(() => import('./pages/DashboardPage'));
const BusinessIdeasPage = lazy(() => import('./pages/BusinessIdeasPage'));
const BusinessIdeaDetailPage = lazy(() => import('./pages/BusinessIdeaDetailPage'));
const RoadmapsPage = lazy(() => import('./pages/RoadmapsPage'));
const RoadmapDetailPage = lazy(() => import('./pages/RoadmapDetailPage'));
const MentorsPage = lazy(() => import('./pages/MentorsPage'));
const MentorDetailPage = lazy(() => import('./pages/MentorDetailPage'));
const ResourcesPage = lazy(() => import('./pages/ResourcesPage'));
const SkillAssessmentPage = lazy(() => import('./pages/SkillAssessmentPage'));
const ProfilePage = lazy(() => import('./pages/ProfilePage'));
const BookmarksPage = lazy(() => import('./pages/BookmarksPage'));
const NotFoundPage = lazy(() => import('./pages/NotFoundPage'));

const ComingSoonPage = ({ title }) => (
  <div className="min-h-screen flex items-center justify-center bg-dark-50 dark:bg-dark-900">
    <div className="text-center">
      <h1 className="text-5xl font-bold gradient-text mb-4">{title}</h1>
      <p className="text-dark-500 text-lg">Coming Soon! 🚀</p>
      <a href="/" className="btn-primary mt-6 inline-flex">← Back to Home</a>
    </div>
  </div>
);

function App() {
  const { loading } = useAuth();
  if (loading) return <PageLoader message="Initializing EntreSkillHub..." />;

  return (
    <Suspense fallback={<PageLoader message="Loading page..." />}>
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/about" element={<ComingSoonPage title="About Us" />} />
        <Route path="/contact" element={<ComingSoonPage title="Contact" />} />

        <Route path="/business-ideas" element={<BusinessIdeasPage />} />
        <Route path="/business-ideas/:identifier" element={<BusinessIdeaDetailPage />} />

        <Route path="/roadmaps" element={<RoadmapsPage />} />
        <Route path="/roadmaps/:identifier" element={<RoadmapDetailPage />} />

        <Route path="/resources" element={<ResourcesPage />} />
        <Route path="/resources/:identifier" element={<ComingSoonPage title="Resource Details" />} />

        <Route path="/mentors" element={<MentorsPage />} />
        <Route path="/mentors/:identifier" element={<MentorDetailPage />} />

        <Route path="/login" element={<PublicOnlyRoute><LoginPage /></PublicOnlyRoute>} />
        <Route path="/register" element={<PublicOnlyRoute><RegisterPage /></PublicOnlyRoute>} />
        <Route path="/forgot-password" element={<ComingSoonPage title="Forgot Password" />} />
        <Route path="/reset-password/:token" element={<ComingSoonPage title="Reset Password" />} />
        <Route path="/verify-email/:token" element={<ComingSoonPage title="Verify Email" />} />

        <Route path="/dashboard" element={<ProtectedRoute><DashboardPage /></ProtectedRoute>} />
        <Route path="/profile" element={<ProtectedRoute><ProfilePage /></ProtectedRoute>} />
        <Route path="/skill-assessment" element={<ProtectedRoute><SkillAssessmentPage /></ProtectedRoute>} />
        <Route path="/bookmarks" element={<ProtectedRoute><BookmarksPage /></ProtectedRoute>} />
        <Route path="/sessions" element={<ProtectedRoute><ComingSoonPage title="My Sessions" /></ProtectedRoute>} />

        <Route path="/become-mentor" element={<ProtectedRoute><ComingSoonPage title="Become a Mentor" /></ProtectedRoute>} />
        <Route path="/mentor/dashboard" element={<ProtectedRoute roles={['mentor', 'admin', 'superadmin']}><ComingSoonPage title="Mentor Dashboard" /></ProtectedRoute>} />

        <Route path="/admin/*" element={<ProtectedRoute roles={['admin', 'superadmin']}><ComingSoonPage title="Admin Panel" /></ProtectedRoute>} />

        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </Suspense>
  );
}

export default App;
